xwikidoc.content:
{{include reference="ReleaseNotes.Code.Change.ChangeDisplayerVelocityMacros"/}}
{{velocity}} ## Inputs: ## - $changeItems ## - $columns ## - $displayEditLink #set ($discard = $xwiki.ssx.use("ReleaseNotes.Code.Change.ChangeDisplayerGrid")) ## Each change is a self-contained card, and the cards are laid out by CSS grid rather than chunked into rows of ## Bootstrap columns. Both choices serve the same goal: a reader must never be able to attach a screenshot to the ## neighbouring change. The card draws the boundary, and the grid removes the row, whose cells all grew to the ## height of the tallest change and left large gaps in between. ## The column count travels to the stylesheet as a custom property so that the media queries can lower it on ## narrow screens. #set ($gridColumns = $numbertool.toNumber("$!columns")) #if (!$gridColumns || $gridColumns.intValue() < 1) #set ($gridColumns = 2) #end (% class="rn-changes-grid" style="--rn-changes-grid-columns: $gridColumns" %)((( #foreach ($item in $changeItems) #loadChangeView($item, $displayEditLink) (% class="rn-change-card" %)((( ## The title comes first so that the media below it can only be read as illustrating this change. #if ($title != '') (% class="rn-change-title" %) === $title${displayEditLinkMarkup}=== #end
## Every card gets a media block, which is what $alwaysDisplayScreenshots buys: the screenshots when the ## change has any, its video when it has no screenshot, and the "no image" placeholder when it has neither. ## A card therefore never stacks a video under a gallery, which would make it half again as tall as the ## change beside it. (% class="rn-change-media" %)((( #displayScreenshots($changeObject, true, true) )))
$changeSummary$summaryEditLinkMarkup #if ($moreDetailsLinkMarkup != '')
(% class="rn-change-details" %)$moreDetailsLinkMarkup #end ))) #end ))) {{/velocity}}

property.code:
/* The colour theme drives the whole card chrome, so the grid stays native-looking under any theme. */
.rn-changes-grid {
  display: grid;
  /* The column count is set inline by the displayer, from the macro parameter. */
  grid-template-columns: ~"repeat(var(--rn-changes-grid-columns, 2), minmax(0, 1fr))";
  align-items: start;
  gap: 20px;
  margin-bottom: 20px;

  /* Below these widths a card gets too narrow to read a screenshot in, so lower the column count. Never raise
     it: a report asking for a single column must stay on one column. */
  @media (max-width: 991px) {
    grid-template-columns: ~"repeat(min(2, var(--rn-changes-grid-columns, 2)), minmax(0, 1fr))";
  }

  @media (max-width: 767px) {
    grid-template-columns: minmax(0, 1fr);
  }

  /* The border, the padding and the background are what tie a screenshot to its own change instead of to the
     change displayed next to it. */
  .rn-change-card {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 15px 20px 20px;
    border: 1px solid @xwiki-border-color;
    border-radius: @border-radius-base;
    background-color: @xwiki-page-content-bg;
    /* Themes where the page background already is the card background need the shadow to keep the card readable
       as one block. */
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
    /* Neither an unbreakable title nor an oversized screenshot may bleed out of the card. */
    overflow: hidden;
    overflow-wrap: break-word;

    > * {
      margin-top: 0;
      margin-bottom: 0;
    }

    /* A code sample is the one piece of content that legitimately does not wrap, so let it scroll rather than
       let the card clip it. */
    pre {
      max-width: 100%;
      overflow-x: auto;
    }
  }

  .rn-change-title {
    font-size: 1.2em;
    line-height: 1.3;
    padding-bottom: 10px;
    border-bottom: 1px solid @xwiki-border-color;
  }

  .rn-change-media {
    padding: 10px;
    border-radius: @border-radius-base;
    background-color: @gray-lighter;
    text-align: center;

    /* The gallery and the video macros both ask for a fixed width, which overflows a card in a narrow column. */
    img,
    video,
    .gallery {
      max-width: 100%;
    }
  }

  /* Pushed to the bottom of the card so that the link sits in the same place in every card of a row. */
  .rn-change-details {
    margin-top: auto;
    padding-top: 5px;
    font-size: 0.9em;
    color: @gray-light;
  }

  /* The edit pencil is a maintenance affordance: keep it out of the way until the card is pointed at, but never
     out of reach of the keyboard. */
  .rn-change-card .edit_section {
    margin-left: 5px;
    font-size: 0.8em;
    opacity: 0;
    transition: opacity 0.15s ease-in-out;
  }

  .rn-change-card:hover .edit_section,
  .rn-change-card .edit_section:focus {
    opacity: 1;
  }
}
